  /**
   * allSpams iterates over GET /v1/ip/{ip}/spam (List spam blocks).
   *
   * It lists the IDs with {@link IpApi.listSpams}, then gets each object with
   * {@link IpApi.getSpam}, only when the loop reaches it. An object deleted in the
   * meantime is skipped. Any other error is thrown and stops the loop.
   *
   * The two calls require the IAM action ip:apiovh:spam/get.
   *
   * @param ip - the ip path parameter
   * @param params - the optional parameters
   * @param options - the options of this call: signal, timeout, headers
   * @returns each {@link models.IPSpamIP}, one at a time: loop with `for await`
   * @throws ForbiddenError when the policy lacks an IAM action this call requires
   * @example
   * for await (const item of client.ip.allSpams(ip)) console.log(item);
   */
  allSpams(
    ip: models.IPBlock,
    params?: {
      /** Filter the value of state property (=) */
      state?: models.IPSpamStateEnum | undefined;
    },
    options?: RequestOptions,
  ): AsyncIterable<models.IPSpamIP> {
    return this._each(
      () => this.listSpams(ip, params, options),
      (listedId) => this.getSpam(ip, listedId, options),
    );
  }

